(* [comment removed for export] *)
Definition inv (Mi : word -> option byte) (mdi : Model) (cri : credit) (ki : PESK.sink) (a : Z) : Prop :=
  L5.u64_at RSEGS Mi (sp - 8) (bv_unsigned (getr R (PMK.reg 1))) /\ L5.u64_at RSEGS Mi (sp - 16) (bv_unsigned (getr R (PMK.reg 8)))
  /\ L5.u64_at RSEGS Mi (sp - 24) (bv_unsigned (getr R (PMK.reg 9))) /\ L5.u64_at RSEGS Mi (sp - 32) (bv_unsigned (getr R (PMK.reg 18)))
  /\ L5C.stk (hl_sptop L) Mi sp 20480 /\ model_but_vm model mdi /\ PMSP.model_ok mdi
  /\ hi_heap HI (PEC.owned s en ki ++ LBX) cri Mi (m_vmmaps mdi)
  /\ enc_at Mi (fb + 440) fb en /\ PESK.sink_at RSEGS L PMSP.T3 PMSP.T4 P Mi (fb + 496) ki
  /\ xlo + a <= PESK.sk_z ki <= xhi + a
  /\ PMK.ek L LBc0 sp 20480 Ws M Mi /\ PMK.dk L LBc0 sp 20480 M Mi
  /\ PMSP.credit_keep cr cri (PEC.pot_enc L P en k) (PEC.pot_enc L P en ki).

